const modp = (n, p) => {
  // Use BigInt for safe modular exponentiation
  const bigN = BigInt(n);
  const bigP = BigInt(p);
  if (bigP === 0n) return NaN; // modulo by zero is undefined
  let result = 1n;
  let base = 2n % bigP;
  let exp = bigN;
  while (exp > 0n) {
    if (exp & 1n) {
      result = (result * base) % bigP;
    }
    base = (base * base) % bigP;
    exp >>= 1n;
  }
  // Convert back to Number if within safe integer range
  const numResult = Number(result);
  return Number.isSafeInteger(numResult) ? numResult : result;
};

